const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Rectangle([45, -15, 51, -12]); // Northern Madagascar
    const startDateInterest = ee.Date('2018-12-01');
    const endDateInterest = ee.Date('2019-01-31');
    const startYearLongTerm = 2000;
    const endYearLongTerm = 2019; // Inclusive, used for calculating the number of years.

    // 2. Data Acquisition
    const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');
    const precipitationBand = 'precipitation';

    // 3. Calculation for the Period of Interest (Dec 2018 - Jan 2019)
    const interestCollection = chirps.filterDate(startDateInterest, endDateInterest.advance(1, 'day'));
    const interestCollectionSize = interestCollection.size().getInfo();

    if (interestCollectionSize === 0) {
        console.log('Evidence: No images found for Dec 2018 - Jan 2019.');
        console.log('C1');
        return;
    }

    const totalPrecipitationInterest = interestCollection.sum();
    const meanPrecipitationInterest = totalPrecipitationInterest.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geometry,
        scale: 5000,
        maxPixels: 1e9
    }).get(precipitationBand);

    const interestValue = ee.Number(meanPrecipitationInterest).getInfo();
    if (interestValue === null) {
        console.log('Evidence: Failed to calculate precipitation for 2018-2019.');
        console.log('C3');
        return;
    }
    console.log(`Dec 2018 - Jan 2019 Total Rainfall (mm): ${interestValue.toFixed(2)}`);

    // 4. Calculation for Long-Term Average (Dec/Jan from 2000-2019)
    const years = ee.List.sequence(startYearLongTerm, endYearLongTerm - 1);
    const byYear = ee.ImageCollection.fromImages(
        years.map(function(y) {
            const start = ee.Date.fromYMD(y, 12, 1);
            const end = start.advance(2, 'month');
            const yearCollection = chirps.filterDate(start, end);
            const total = yearCollection.sum().set('year', y);
            return total;
        })
    );

    const longTermCollectionSize = byYear.size().getInfo();
    if (longTermCollectionSize === 0) {
        console.log('Evidence: No images found for the long-term period.');
        console.log('C1');
        return;
    }

    const longTermMean = byYear.mean();
    const meanPrecipitationLongTerm = longTermMean.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geometry,
        scale: 5000,
        maxPixels: 1e9
    }).get(precipitationBand);

    const longTermValue = ee.Number(meanPrecipitationLongTerm).getInfo();
     if (longTermValue === null) {
        console.log('Evidence: Failed to calculate long-term average precipitation.');
        console.log('C3');
        return;
    }
    console.log(`Long-Term Dec/Jan Avg Rainfall (mm): ${longTermValue.toFixed(2)}`);

    // 5. Comparison and Final Answer
    const isLess = interestValue < longTermValue;
    console.log(`Comparison: ${interestValue.toFixed(2)} < ${longTermValue.toFixed(2)} is ${isLess}.`);

    if (isLess) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
